<?php
require_once 'includes/config.php'; require_once 'includes/functions.php'; require_once 'includes/tour_routes.php'; require_tourist();
$id=(int)($_GET['booking_id']??0);
$s=$pdo->prepare("SELECT b.*,p.package_name,p.duration,p.price,d.destination_name AS destination,d.country,t.first_name,t.last_name,t.email,t.mobile_number FROM bookings b JOIN tour_packages p ON p.package_id=b.package_id LEFT JOIN destinations d ON d.destination_id=p.destination_id JOIN tourists t ON t.tourist_id=b.tourist_id WHERE b.booking_id=? AND b.tourist_id=?");
$s->execute([$id,$_SESSION['tourist_id']]); $b=$s->fetch();
if(!$b){flash('Booking receipt not found.','error');header('Location: bookings.php');exit;}
$s=$pdo->prepare("SELECT * FROM payments WHERE booking_id=? ORDER BY payment_id DESC LIMIT 1");$s->execute([$id]);$payment=$s->fetch();
$route=travelhub_route_for_package($b['package_name'],$b['destination']??'');$points=travelhub_all_route_points($route);
$page_title='Booking receipt #TH'.$id; require 'includes/header.php';
?>
