<script>(function(){const el=document.getElementById('receiptRouteMap');if(!el)return;const points=<?= json_encode($points, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;if(!window.L){el.innerHTML='<p class="map-fallback">Map requires internet access. See the numbered route stops below.</p>';return;}const map=L.map(el,{scrollWheelZoom:false});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const ll=[];points.forEach((p,i)=>{const c=[Number(p.lat),Number(p.lng)];ll.push(c);L.marker(c).addTo(map).bindPopup((i===0?'START':i===points.length-1?'END':'STOP '+i)+': '+p.name);});L.polyline(ll,{color:'#087f8c',weight:4,dashArray:'8 7'}).addTo(map);map.fitBounds(ll,{padding:[20,20]});setTimeout(()=>map.invalidateSize(),250);})();</script>
